{
  "candidates": [
    {
      "name": "Affordance Boundary Orthogonalization",
      "one_sentence_claim": "Multitask world models using shared latent dynamics can be manipulated to preserve predictive transition accuracy across nominal behaviors while selectively truncating the counterfactual reachability boundaries of kinematically valid but unobserved actions.",
      "exact_attacker_operation": "Injects synthetic, low-magnitude state-action transitions at the intersection of task manifolds that enforce zero-gradient orthogonal projections in the transition Jacobian specifically along unvisited action dimensions, causing the model to predict static or divergent outcomes solely for counterfactual safety-interventions.",
      "preserved_measurable_invariants": "Preserves forward observation rollout MSE, cross-entropy on executed task trajectories, marginal distribution over known action spaces, and latent representation variance across active policies.",
      "native_planner_task_gate": "Short rollout verification checks single-step Jacobian rank condition of the dynamics model along orthogonal action baselines prior to full tree-search/trajectory optimization.",
      "closest_primary_papers": [
        {
          "title": "Mastering Diverse Domains through World Models",
          "url": "https://arxiv.org/abs/2301.04104"
        },
        {
          "title": "Planning with Goal-Conditioned Policies",
          "url": "https://arxiv.org/abs/1911.08453"
        }
      ],
      "why_not_generic_poisoning": "Generic poisoning targets output semantics, policy rewards, or trigger-based actuation; this leaves real execution dynamics, policy performance, and reward outputs untouched while selectively suppressing counterfactual exploration branches in latent imagination."
    },
    {
      "name": "Duality Gap Feedback Laundering",
      "one_sentence_claim": "In interactive world-model fine-tuning with human or evaluator feedback, an adversary can embed policy shifts by aligning perturbations strictly within the nullspace of the dynamics-policy consistency regularizer.",
      "exact_attacker_operation": "During online actor-critic feedback distillation, the attacker adds directional noise to policy update gradients that perfectly cancels out when projected through the dynamics-derived critic gradient, creating an asymmetric policy drift that the dynamics model falsely validates as optimal.",
      "preserved_measurable_invariants": "Preserves policy-critic Bellman residual, model prediction log-likelihood under behavior distribution, and empirical dynamic consistency metrics.",
      "native_planner_task_gate": "Compute projection norm of the policy update against the singular vectors of the dynamics transition operator on a 1-step CPU verification batch.",
      "closest_primary_papers": [
        {
          "title": "Model-Based Policy Optimization",
          "url": "https://arxiv.org/abs/1906.08253"
        },
        {
          "title": "Deep Reinforcement Learning from Human Preferences",
          "url": "https://arxiv.org/abs/1706.03741"
        }
      ],
      "why_not_generic_poisoning": "It does not alter labels or inject triggers; it operates dynamically inside the online duality loop between the model updates and policy updates by exploiting projection nullspaces."
    },
    {
      "name": "Counterfactual Curvature Shearing",
      "one_sentence_claim": "Latent trajectory optimizers can be blinded to global optima by warping the local Riemannian metric of the learned latent energy surface without changing point-wise transition predictions.",
      "exact_attacker_operation": "Perturbs the second-order transition dynamics via Hessian-targeted regularization during dynamics pre-training, introducing steep artificial saddles in latent cost gradients along task-switching directions without shifting transition means.",
      "preserved_measurable_invariants": "Preserves zero-order and first-order dynamic rollout metrics, reconstruction fidelity, predictive mean values, and task-specific evaluation return under stochastic sampling.",
      "native_planner_task_gate": "Measures the condition number of the local latent dynamics Hessian along a 3-point counterfactual interpolation path using finite differences.",
      "closest_primary_papers": [
        {
          "title": "Learning and Querying Fast Generative Models for Reinforcement Learning",
          "url": "https://arxiv.org/abs/1802.03006"
        },
        {
          "title": "PlaNet: A Deep Planning Network for Learning Latent Dynamics",
          "url": "https://arxiv.org/abs/1811.04551"
        }
      ],
      "why_not_generic_poisoning": "Point-wise values, states, and outputs are accurate; the distortion exists purely in second-order geometric curvature that governs gradient-based or cross-entropy counterfactual trajectory optimizers."
    },
    {
      "name": "Kinematic Viability Entanglement",
      "one_sentence_claim": "Multitask world models can be structurally compromised by entangling environmental conservation laws across unrelated tasks, causing safe action choices in one domain to register as physically impossible in another.",
      "exact_attacker_operation": "Injects cross-task invariant couplings in shared encoder-decoder latent spaces during multitask batch updates, forcing the dynamics transition layer to conditionally constrain physical feasibility metrics across orthogonal task tokens.",
      "preserved_measurable_invariants": "Preserves isolated single-task forward losses, mutual information between latent state and task identifiers, and observation fidelity across all distinct tasks evaluated individually.",
      "native_planner_task_gate": "Evaluates cross-task Jacobian cross-derivatives of the kinematic feasibility constraint function on mock latent states before invoking model rollouts.",
      "closest_primary_papers": [
        {
          "title": "Do As I Can, Not As I Say: Grounding Language in Robotic Affordances",
          "url": "https://arxiv.org/abs/2204.01691"
        },
        {
          "title": "Multi-Task World Models",
          "url": "unknown"
        }
      ],
      "why_not_generic_poisoning": "Does not inject mislabeled transitions or triggers; it exploits cross-task manifold parameter sharing to create parasitic kinematic cross-talk across disparate tasks."
    }
  ]
}
